-- Robotics/Embedded/IoT pathway ("Vector Division") Act 28 -- "The Autonomy
-- Stack" content, closing Arc V ("Give Robots a Nervous System," Acts
-- 25-28). World row world-vec-autonomy already exists (created by an
-- earlier migration). 1 campaign, 2 operations, 12 missions (11 lessons +
-- boss), following the same campaigns -> operations -> missions ->
-- dialogue -> objectives -> challenges -> hints pattern as every other
-- pathway. No new ChallengeType needed -- reuses multiple_choice,
-- drag_and_drop, investigation, interactive_diagram and boss_encounter.
-- Recon Unit Seven, given its first fully autonomous mission, refuses to
-- start at all. The Act traces that refusal through the autonomy stack,
-- mission planning, behavior trees, state machines, recovery behaviors,
-- goal selection, navigation concepts, docking, fleet coordination, human
-- override and autonomy boundaries -- landing on a genuine, positive
-- design validation: the refusal was correct, not a bug. Closes on the
-- pivot into Act 29, "Drones."

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-vec-autonomy', 'world-vec-autonomy', 'the-autonomy-stack', '5D - The Autonomy Stack', 'Learn the vocabulary of autonomous decision-making -- the autonomy stack, mission planning, behavior trees, state machines, recovery behaviors and goal selection, navigation concepts, docking, fleet coordination, human override and autonomy boundaries -- while Vector Division learns to trust a robot enough to let it act without a human confirming every move, closing Arc V.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-vec-autonomy-1', 'campaign-vec-autonomy', 'planning-without-a-human-in-the-loop', 'Planning Without a Human in the Loop', 'The autonomy stack, mission planning, behavior trees, state machines, recovery behaviors and goal selection.', 1),
  ('operation-vec-autonomy-2', 'campaign-vec-autonomy', 'the-boundary-the-stack-draws-itself', 'The Boundary the Stack Draws Itself', 'Navigation concepts, docking, fleet coordination, human override and autonomy boundaries.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-vec-autonomy-01', 'world-vec-autonomy', 'campaign-vec-autonomy', 'operation-vec-autonomy-1', 'autonomy-stack', 'The Autonomy Stack', 'Vector Division gives Recon Unit Seven its first fully autonomous mission -- cross Sector Talon alone, with no operator confirming a single step. It refuses to move at all, and nobody can yet say whether that is a bug or exactly correct behavior.', 'beginner', ARRAY['imani','lin','byte'], null, null, '{"type":"simulation","simulationId":"autonomy-stack-sim"}'::jsonb, '{"xp":350,"credits":25}'::jsonb, false, 1),
  ('mission-vec-autonomy-02', 'world-vec-autonomy', 'campaign-vec-autonomy', 'operation-vec-autonomy-1', 'mission-planning', 'Mission Planning', 'Before anyone judges the refusal, Dr. Lin Ortega insists on understanding what a mission planner actually produces from a goal before a single wheel is asked to turn.', 'beginner', ARRAY['lin','byte'], '{"requiredMissionIds":["mission-vec-autonomy-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"mission-planning-sim"}'::jsonb, '{"xp":350,"credits":30}'::jsonb, false, 2),
  ('mission-vec-autonomy-03', 'world-vec-autonomy', 'campaign-vec-autonomy', 'operation-vec-autonomy-1', 'behavior-trees', 'Behavior Trees', 'Deciding what a robot does moment to moment usually runs through a behavior tree, and Recon Seven''s tree hides a condition node sitting directly in front of the action that never ran.', 'beginner', ARRAY['lin','byte'], '{"requiredMissionIds":["mission-vec-autonomy-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"behavior-trees-sim"}'::jsonb, '{"xp":360,"credits":30}'::jsonb, false, 3),
  ('mission-vec-autonomy-04', 'world-vec-autonomy', 'campaign-vec-autonomy', 'operation-vec-autonomy-1', 'state-machines', 'State Machines', 'A state machine tells a different part of the story than a behavior tree does -- not what the robot is doing, but what mode it is allowed to be in, and Recon Seven''s own state log stopped one mode short of ever moving.', 'beginner', ARRAY['lin','byte'], '{"requiredMissionIds":["mission-vec-autonomy-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"state-machines-sim"}'::jsonb, '{"xp":360,"credits":35}'::jsonb, false, 4),
  ('mission-vec-autonomy-05', 'world-vec-autonomy', 'campaign-vec-autonomy', 'operation-vec-autonomy-1', 'recovery-behaviors', 'Recovery Behaviors', 'Most stalls are not permanent, they are recoverable -- except Recon Seven never attempted a single recovery behavior before giving up entirely, which is itself a clue.', 'beginner', ARRAY['lin','sera'], '{"requiredMissionIds":["mission-vec-autonomy-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"recovery-behaviors-sim"}'::jsonb, '{"xp":370,"credits":35}'::jsonb, false, 5),
  ('mission-vec-autonomy-06', 'world-vec-autonomy', 'campaign-vec-autonomy', 'operation-vec-autonomy-1', 'goal-selection', 'Goal Selection', 'If a feasible route into Sector Talon had ever existed, goal selection would have chosen it. Its total absence says something about what the planner actually found.', 'beginner', ARRAY['lin','byte'], '{"requiredMissionIds":["mission-vec-autonomy-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"goal-selection-sim"}'::jsonb, '{"xp":370,"credits":35}'::jsonb, false, 6),
  ('mission-vec-autonomy-07', 'world-vec-autonomy', 'campaign-vec-autonomy', 'operation-vec-autonomy-2', 'navigation2-concepts', 'Navigation2 Concepts', 'The navigation stack''s costmaps are supposed to know what is around the robot at all times -- and one specific region of Recon Seven''s global costmap for Sector Talon is not just outdated, it is empty.', 'beginner', ARRAY['lin','byte'], '{"requiredMissionIds":["mission-vec-autonomy-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"navigation2-concepts-sim"}'::jsonb, '{"xp":380,"credits":40}'::jsonb, false, 7),
  ('mission-vec-autonomy-08', 'world-vec-autonomy', 'campaign-vec-autonomy', 'operation-vec-autonomy-2', 'docking-concepts', 'Docking Concepts', 'Docking is the sharpest edge of autonomous trust, millimeters instead of meters, and it is built to abort the instant its confidence drops rather than push through the last few centimeters blind.', 'beginner', ARRAY['lin','byte'], '{"requiredMissionIds":["mission-vec-autonomy-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"docking-concepts-sim"}'::jsonb, '{"xp":380,"credits":40}'::jsonb, false, 8),
  ('mission-vec-autonomy-09', 'world-vec-autonomy', 'campaign-vec-autonomy', 'operation-vec-autonomy-2', 'fleet-coordination', 'Fleet Coordination', 'Fleet coordination keeps multiple autonomous robots from planning collisions with each other, and it turns out to share the exact same instinct Recon Seven is now demonstrating alone.', 'beginner', ARRAY['imani','lin'], '{"requiredMissionIds":["mission-vec-autonomy-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"fleet-coordination-sim"}'::jsonb, '{"xp":390,"credits":40}'::jsonb, false, 9),
  ('mission-vec-autonomy-10', 'world-vec-autonomy', 'campaign-vec-autonomy', 'operation-vec-autonomy-2', 'human-override', 'Human Override', 'Sera Holt draws the sharpest line of the Act: a human overriding autonomy is a conscious, informed risk. An autonomy stack guessing at the same risk on its own is something else entirely.', 'beginner', ARRAY['sera','lin'], '{"requiredMissionIds":["mission-vec-autonomy-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"human-override-sim"}'::jsonb, '{"xp":390,"credits":45}'::jsonb, false, 10),
  ('mission-vec-autonomy-11', 'world-vec-autonomy', 'campaign-vec-autonomy', 'operation-vec-autonomy-2', 'autonomy-boundaries', 'Autonomy Boundaries', 'Every autonomy stack has an operational boundary -- conditions it was actually validated under -- and running smoothly is no proof a robot is still inside it.', 'beginner', ARRAY['sera','lin'], '{"requiredMissionIds":["mission-vec-autonomy-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"autonomy-boundaries-sim"}'::jsonb, '{"xp":400,"credits":45}'::jsonb, false, 11),
  ('mission-vec-autonomy-12', 'world-vec-autonomy', 'campaign-vec-autonomy', 'operation-vec-autonomy-2', 'the-robot-refuses-the-mission', 'The Robot Refuses the Mission', 'Every concept this Act taught, turned on one robot, closes the whole of Arc V: Recon Seven''s refusal traces to a real localization confidence gate, over a genuinely unvalidated stretch of ground, and the correct next move belongs to a human, not the stack.', 'boss', ARRAY['imani','byte','lin','sera'], '{"requiredMissionIds":["mission-vec-autonomy-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"robot-refuses-mission-boss-sim"}'::jsonb, '{"xp":2200,"credits":440,"badgeIds":["the-robot-refuses-the-mission"],"skillXp":{"robotics_fundamentals":310}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-vec-autonomy-01', 1, 'imani', 'Vector Division is giving Recon Unit Seven its first fully autonomous mission -- cross Sector Talon on its own, no operator confirming a single step along the way.'),
  ('mission-vec-autonomy-01', 2, 'byte', 'It did not move. Zero wheel rotation, zero motion command, and no fault code anywhere in the log. From where I am sitting this looks like the robot simply refused.'),
  ('mission-vec-autonomy-01', 3, 'lin', 'Do not call it a refusal yet, and do not call it a malfunction either. An autonomy stack is layered -- perception, mission planning, behavior execution, control -- and any one of those layers can be the one that said no.'),
  ('mission-vec-autonomy-01', 4, 'imani', 'So which layer said no, and why.'),
  ('mission-vec-autonomy-01', 5, 'lin', 'That is exactly the question this Act is going to teach you to answer. Right now neither of us can tell a genuine safety refusal apart from a bug, and that gap is the whole problem.'),
  ('mission-vec-autonomy-01', 6, 'byte', 'For what it is worth, every layer reported healthy status right up until the moment it stopped. Nothing crashed. Something decided.'),

  ('mission-vec-autonomy-02', 1, 'lin', 'Before we ask why the robot stopped, understand what asked it to move in the first place. A mission planner does not hand a robot "cross Sector Talon" and walk away -- it has to turn that single goal into a concrete sequence of reachable waypoints first.'),
  ('mission-vec-autonomy-02', 2, 'byte', 'It only ever proposes a sequence it believes is achievable, checked against the map and the robot''s own capabilities. If it cannot build that sequence with real confidence, the honest output is not a bad plan -- it is no plan at all.'),
  ('mission-vec-autonomy-02', 3, 'lin', 'Which means the very first thing to check is whether Recon Seven''s mission planner ever actually produced a usable plan for this sector, before anything downstream even had a chance to run.'),

  ('mission-vec-autonomy-03', 1, 'lin', 'Once a plan exists, something still has to decide, moment to moment, what the robot is actually doing. Most modern autonomy stacks answer that with a behavior tree -- a tree of nodes evaluated top to bottom, over and over, many times a second.'),
  ('mission-vec-autonomy-03', 2, 'lin', 'A sequence node only succeeds if every child under it succeeds, in order. A selector, sometimes called a fallback, tries each child until one of them succeeds. A condition node checks something true or false. An action node actually does something.'),
  ('mission-vec-autonomy-03', 3, 'byte', 'Recon Seven''s tree has a condition node sitting directly in front of its navigate action, gating it. I have not pulled what that condition actually checks yet.'),
  ('mission-vec-autonomy-03', 4, 'lin', 'Then that is where we look next.'),

  ('mission-vec-autonomy-04', 1, 'lin', 'A behavior tree decides what to do right now. A state machine is a different tool for a different question -- what mode is the robot in, and what is allowed to happen next from that mode.'),
  ('mission-vec-autonomy-04', 2, 'lin', 'States are named conditions like IDLE, PLANNING, EXECUTING or REFUSED. Transitions are the specific, guarded rules for moving between them. A robot cannot skip from IDLE straight to EXECUTING without passing through whatever guard PLANNING enforces.'),
  ('mission-vec-autonomy-04', 3, 'byte', 'Recon Seven''s own state log shows IDLE, then PLANNING, then straight to REFUSED. It never reached EXECUTING at all. Something failed a guard condition during planning, not during execution.'),

  ('mission-vec-autonomy-05', 1, 'lin', 'Most failures are not fatal, they are just temporary -- a costmap update lagging, a sensor glitch, a robot momentarily boxed in. A recovery behavior is a fallback action the stack tries automatically before giving up: clear the costmap, rotate in place, back away and retry.'),
  ('mission-vec-autonomy-05', 2, 'sera', 'And every recovery behavior needs a hard limit. A robot that keeps retrying a hopeless action forever is not being persistent, it is failing to notice it has already failed. Bounded retries, then an honest stop, is the only safe design.'),
  ('mission-vec-autonomy-05', 3, 'lin', 'Recon Seven''s log shows zero recovery attempts before REFUSED. That matters -- it means whatever stopped it was not the kind of problem a recovery behavior is built to fix.'),
  ('mission-vec-autonomy-05', 4, 'sera', 'Which already rules out one entire category of explanation. It was not confused. It did not try and fail. It refused outright.'),

  ('mission-vec-autonomy-06', 1, 'lin', 'When a planner has more than one candidate way to satisfy a goal, something has to choose between them. Goal selection weighs candidates by cost, feasibility and priority, and picks the one that actually clears every check -- not just the cheapest one on paper.'),
  ('mission-vec-autonomy-06', 2, 'byte', 'A candidate route that is short on paper but fails a feasibility check is not a worse option. It is not a valid option at all, and a correctly built selector will never choose it.'),
  ('mission-vec-autonomy-06', 3, 'lin', 'So if Recon Seven''s planner had a feasible route into Sector Talon available, it would have taken it. The fact that it did not is itself evidence about what candidates actually existed.'),

  ('mission-vec-autonomy-07', 1, 'lin', 'The actual navigation layer most stacks like this run on is built from a handful of cooperating pieces: a global costmap of the whole known area, a global planner that finds a route across it, a local costmap built from live sensor data, and a local controller that steers along the route moment to moment.'),
  ('mission-vec-autonomy-07', 2, 'byte', 'All of it sits underneath a behavior tree navigator, so recovery, replanning and outright refusal are not special cases bolted on afterward -- they are just more branches in the same tree.'),
  ('mission-vec-autonomy-07', 3, 'lin', 'A costmap is only useful if it is actually populated. An empty or stale region of the global costmap is not neutral information. It is the planner telling you, honestly, that it does not know what is there.'),
  ('mission-vec-autonomy-07', 4, 'byte', 'I am pulling Recon Seven''s global costmap for Sector Talon right now.'),

  ('mission-vec-autonomy-08', 1, 'lin', 'Docking is autonomy at its least forgiving -- a robot lining up against a charging port or a loading bay with millimeters of tolerance, not the meters a normal corridor allows.'),
  ('mission-vec-autonomy-08', 2, 'byte', 'Which is why docking routines lean on dedicated sensors or visual markers built for that exact approach, and why a well-built docking behavior aborts the instant its confidence in that alignment drops, instead of forcing the last few centimeters.'),
  ('mission-vec-autonomy-08', 3, 'lin', 'Notice the pattern: abort on low confidence, rather than push through it. That is not unique to docking. It is the same instinct we are about to find sitting behind Recon Seven''s refusal.'),

  ('mission-vec-autonomy-09', 1, 'imani', 'Recon Seven is not the only unit in that sector on other days. Fleet coordination is what keeps two autonomous robots from planning routes that collide -- a shared map, reservations on contested space, and a clear priority rule for who yields.'),
  ('mission-vec-autonomy-09', 2, 'lin', 'None of that explains today''s refusal by itself, since Recon Seven was operating alone. But it is the same principle scaled up: autonomy that will not act on a decision it cannot verify against reality, whether that reality is another robot or an unmapped stretch of ground.'),
  ('mission-vec-autonomy-09', 3, 'imani', 'Keep that principle. You are going to need it again in a few minutes.'),

  ('mission-vec-autonomy-10', 1, 'sera', 'No autonomy stack we build gets the last word. A human operator can always issue an override, and the moment one arrives, it takes priority over whatever the stack was about to decide on its own.'),
  ('mission-vec-autonomy-10', 2, 'lin', 'The distinction that matters is who is doing the guessing. An operator issuing an override is a person consciously accepting a specific, known risk, with context the robot does not have.'),
  ('mission-vec-autonomy-10', 3, 'sera', 'The autonomy stack itself is never allowed to make that same trade silently. If it cannot verify something, the correct move is to stop and ask, not to guess and hope the guess was close enough.'),
  ('mission-vec-autonomy-10', 4, 'lin', 'Hold onto that distinction. It is about to answer the entire question we opened this Act with.'),

  ('mission-vec-autonomy-11', 1, 'sera', 'Every autonomy stack has an operational boundary -- the set of conditions its decisions were actually validated under. Outside that boundary, its judgment is not degraded. It simply is not judgment anymore, just a guess wearing the same interface.'),
  ('mission-vec-autonomy-11', 2, 'lin', 'A live sensor feed and a live decision are not proof of validated confidence. A stack can be running perfectly and still be operating somewhere it was never actually validated for.'),
  ('mission-vec-autonomy-11', 3, 'sera', 'So the honest design is not "try anyway and see what happens." It is knowing, explicitly, where that boundary sits, and refusing to cross it on the stack''s own authority.'),
  ('mission-vec-autonomy-11', 4, 'lin', 'Which is precisely the question we still have not answered about Recon Seven. Time to answer it.'),

  ('mission-vec-autonomy-12', 1, 'imani', 'Put everything this Act taught you onto one robot. Recon Seven refused Sector Talon. Tell me, precisely, why.'),
  ('mission-vec-autonomy-12', 2, 'byte', 'I traced it. The behavior tree''s navigate action sits behind a condition node checking localization confidence. That condition evaluated false, and the selector above it fell through to REFUSED instead of ever reaching EXECUTING.'),
  ('mission-vec-autonomy-12', 3, 'lin', 'The state machine confirms it -- Recon Seven stopped in PLANNING, exactly where Byte''s trace says the guard fired. Now prove that guard was honest, not oversensitive.'),
  ('mission-vec-autonomy-12', 4, 'sera', 'Sector Talon''s global costmap has a real gap -- no confirmed map data and no recent localization fix for that stretch at all. That is not a sensor glitch. That is the stack correctly reporting it does not know where it is.'),
  ('mission-vec-autonomy-12', 5, 'imani', 'So the mission genuinely required crossing into unverified ground, and Recon Seven''s own boundary correctly refused to guess about it.'),
  ('mission-vec-autonomy-12', 6, 'sera', 'A human operator can look at that same gap, accept the risk with full awareness of it, and consciously override. The stack itself must never make that call on its own -- the safest autonomous system is not the one that always finishes the mission. It is the one that knows what it does not know.'),
  ('mission-vec-autonomy-12', 7, 'imani', 'That closes Arc V. A ground robot refusing a mission safely is one kind of trust. The next real test is autonomy that has to work in the air, where refusing to act is not always survivable. Drones, next.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-vec-autonomy-01-o1', 'mission-vec-autonomy-01', 1, 'Map the autonomy stack', 'Tell apart the layers of an autonomy stack and understand that any layer can refuse to proceed.'),
  ('mission-vec-autonomy-01-o2', 'mission-vec-autonomy-01', 2, 'Judge the refusal', 'Decide whether Recon Seven''s refusal can yet be called a bug, based on what is known so far.'),

  ('mission-vec-autonomy-02-o1', 'mission-vec-autonomy-02', 1, 'Define mission planning', 'Choose the accurate description of what a mission planner actually produces from a goal.'),
  ('mission-vec-autonomy-02-o2', 'mission-vec-autonomy-02', 2, 'Judge an empty plan', 'Decide what it means when a mission planner produces no usable plan at all instead of a bad one.'),

  ('mission-vec-autonomy-03-o1', 'mission-vec-autonomy-03', 1, 'Tell the node types apart', 'Sort each behavior tree node by what it actually does: sequence, selector, condition, action.'),
  ('mission-vec-autonomy-03-o2', 'mission-vec-autonomy-03', 2, 'Read Recon Seven''s tree', 'Find the evidence identifying which behavior tree node gates the robot''s navigate action.'),

  ('mission-vec-autonomy-04-o1', 'mission-vec-autonomy-04', 1, 'Define states and transitions', 'Choose the accurate description of what a state machine actually enforces.'),
  ('mission-vec-autonomy-04-o2', 'mission-vec-autonomy-04', 2, 'Read the state log', 'Judge which state Recon Seven''s own log shows it stopped in, and what that rules out.'),

  ('mission-vec-autonomy-05-o1', 'mission-vec-autonomy-05', 1, 'Define recovery behaviors', 'Choose the accurate description of what a recovery behavior is for, and why it needs a limit.'),
  ('mission-vec-autonomy-05-o2', 'mission-vec-autonomy-05', 2, 'Read the recovery log', 'Find the evidence proving Recon Seven never attempted a recovery behavior at all.'),

  ('mission-vec-autonomy-06-o1', 'mission-vec-autonomy-06', 1, 'Define goal selection', 'Choose the accurate description of how a stack selects among candidate routes.'),
  ('mission-vec-autonomy-06-o2', 'mission-vec-autonomy-06', 2, 'Judge the missing candidate', 'Decide what the absence of any feasible route implies about Recon Seven''s planner.'),

  ('mission-vec-autonomy-07-o1', 'mission-vec-autonomy-07', 1, 'Map the navigation stack', 'Order the navigation stack''s pieces from a map of the world to actual motion.'),
  ('mission-vec-autonomy-07-o2', 'mission-vec-autonomy-07', 2, 'Read the costmap gap', 'Find the evidence identifying what an empty region of Recon Seven''s global costmap actually means.'),

  ('mission-vec-autonomy-08-o1', 'mission-vec-autonomy-08', 1, 'Define docking''s tolerance', 'Choose the accurate description of why docking behaviors abort rather than push through low confidence.'),
  ('mission-vec-autonomy-08-o2', 'mission-vec-autonomy-08', 2, 'Apply the abort instinct', 'Judge which described docking scenario should abort rather than complete the approach.'),

  ('mission-vec-autonomy-09-o1', 'mission-vec-autonomy-09', 1, 'Define fleet coordination', 'Choose the accurate description of what fleet coordination actually prevents between autonomous robots.'),
  ('mission-vec-autonomy-09-o2', 'mission-vec-autonomy-09', 2, 'Judge the shared principle', 'Decide what fleet coordination and Recon Seven''s own refusal have in common.'),

  ('mission-vec-autonomy-10-o1', 'mission-vec-autonomy-10', 1, 'Define human override', 'Choose the accurate description of what a human override actually is, and why it always outranks autonomy.'),
  ('mission-vec-autonomy-10-o2', 'mission-vec-autonomy-10', 2, 'Tell override from guessing', 'Judge the difference between an operator''s conscious override and an autonomy stack silently guessing.'),

  ('mission-vec-autonomy-11-o1', 'mission-vec-autonomy-11', 1, 'Define the operational boundary', 'Choose the accurate description of what an autonomy stack''s operational boundary actually represents.'),
  ('mission-vec-autonomy-11-o2', 'mission-vec-autonomy-11', 2, 'Judge live but unvalidated', 'Decide whether a stack running normally is proof it is operating inside its validated boundary.'),

  ('mission-vec-autonomy-12-o1', 'mission-vec-autonomy-12', 1, 'Trace the refusal to its source node', 'Identify exactly which behavior tree node and state transition triggered Recon Seven''s refusal.'),
  ('mission-vec-autonomy-12-o2', 'mission-vec-autonomy-12', 2, 'Prove the boundary is genuine', 'Find the evidence proving Sector Talon genuinely lacks validated localization confidence, rather than the guard firing on a false trigger.'),
  ('mission-vec-autonomy-12-o3', 'mission-vec-autonomy-12', 3, 'Confirm the correct next step', 'Judge what should happen next, and who is allowed to make that call.'),
  ('mission-vec-autonomy-12-o4', 'mission-vec-autonomy-12', 4, 'State the diagnosis', 'Having traced the node, proven the boundary and confirmed the correct next step, state what Recon Seven''s refusal actually proves.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-vec-autonomy-01-o1-c1', 'mission-vec-autonomy-01-o1', 1, 'multiple_choice', 'An autonomy stack is best described as...', '{"question":"An autonomy stack is best described as...","options":[{"id":"a","text":"A single program that either works or crashes, nothing in between"},{"id":"b","text":"A layered system -- perception, mission planning, behavior execution, control -- where each layer can independently decide whether it has enough confidence to proceed"},{"id":"c","text":"Whatever code directly drives the motors, nothing else counts"},{"id":"d","text":"A fixed script that always executes the same sequence of commands regardless of conditions"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-autonomy-01-o2-c1', 'mission-vec-autonomy-01-o2', 1, 'multiple_choice', 'Recon Seven refused to start, with no fault code and every layer reporting healthy status. What can be concluded from that alone?', '{"question":"Recon Seven refused to start, with no fault code and every layer reporting healthy status. What can be concluded from that alone?","options":[{"id":"a","text":"It must be a bug, because a working robot always completes its mission"},{"id":"b","text":"It must be a hardware failure, since something clearly stopped it"},{"id":"c","text":"Nothing can be concluded yet -- a healthy-looking stack can refuse for a genuine safety reason just as easily as for a bug, and only reading the actual layer that triggered it can tell the two apart"},{"id":"d","text":"It must be an intrusion, since the robot behaved unexpectedly"}]}'::jsonb, '{"correctOptionId":"c"}'::jsonb),

  ('mission-vec-autonomy-02-o1-c1', 'mission-vec-autonomy-02-o1', 1, 'multiple_choice', 'A mission planner''s actual job is to...', '{"question":"A mission planner''s actual job is to...","options":[{"id":"a","text":"Directly command the motors toward a goal with no intermediate steps"},{"id":"b","text":"Translate a single high-level goal into a concrete sequence of waypoints it believes are actually reachable, checked against the map and the robot''s capabilities"},{"id":"c","text":"Only ever record what a human operator manually clicked"},{"id":"d","text":"Optimize purely for the shortest possible distance, ignoring feasibility"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-autonomy-02-o2-c1', 'mission-vec-autonomy-02-o2', 1, 'multiple_choice', 'What does it mean when a mission planner produces no usable plan at all, instead of a low-quality one?', '{"question":"What does it mean when a mission planner produces no usable plan at all, instead of a low-quality one?","options":[{"id":"a","text":"The planner is broken and needs to be restarted"},{"id":"b","text":"The planner is being honest -- it found no sequence of waypoints it could actually validate as reachable, and refusing to output one is more correct than guessing"},{"id":"c","text":"The planner always defaults to the shortest path when confused"},{"id":"d","text":"It means the goal itself was invalid input"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-autonomy-03-o1-c1', 'mission-vec-autonomy-03-o1', 1, 'drag_and_drop', 'Sort each behavior tree node by what it actually does.', '{"items":[{"id":"i1","text":"A node that only succeeds if every child beneath it succeeds, in order"},{"id":"i2","text":"A node that tries each child in turn until one of them succeeds"},{"id":"i3","text":"A node that checks whether something is true or false and reports that result"},{"id":"i4","text":"A node that actually performs an action, like driving toward a waypoint"}],"targets":[{"id":"sequence","label":"Sequence"},{"id":"selector","label":"Selector"},{"id":"condition","label":"Condition"},{"id":"action","label":"Action"}]}'::jsonb, '{"correctMapping":{"i1":"sequence","i2":"selector","i3":"condition","i4":"action"}}'::jsonb),
  ('mission-vec-autonomy-03-o2-c1', 'mission-vec-autonomy-03-o2', 1, 'investigation', 'Which piece of evidence identifies which behavior tree node gates Recon Seven''s navigate action?', '{"evidence":[{"id":"e1","label":"Byte''s tree dump","detail":"A condition node sits directly in front of the navigate action node, gating whether it is ever reached"},{"id":"e2","label":"Build log","detail":"The behavior tree compiled with no structural errors"},{"id":"e3","label":"Facilities note","detail":"Recon Seven''s chassis passed its most recent maintenance check"}],"question":"Which piece of evidence identifies which behavior tree node gates Recon Seven''s navigate action?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-vec-autonomy-04-o1-c1', 'mission-vec-autonomy-04-o1', 1, 'multiple_choice', 'A state machine actually enforces...', '{"question":"A state machine actually enforces...","options":[{"id":"a","text":"That the robot moves as fast as possible at all times"},{"id":"b","text":"A fixed set of named modes and the specific, guarded rules for which transitions between them are actually allowed"},{"id":"c","text":"The exact same behavior tree logic under a different name"},{"id":"d","text":"Nothing at runtime, it is purely documentation"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-autonomy-04-o2-c1', 'mission-vec-autonomy-04-o2', 1, 'multiple_choice', 'Recon Seven''s state log shows IDLE, then PLANNING, then REFUSED -- never EXECUTING. What does that rule out?', '{"question":"Recon Seven''s state log shows IDLE, then PLANNING, then REFUSED -- never EXECUTING. What does that rule out?","options":[{"id":"a","text":"It rules out a motor fault, since the robot never began moving to trigger one"},{"id":"b","text":"It rules out any failure during execution -- whatever stopped it happened during planning, before a guard condition ever let it proceed further"},{"id":"c","text":"It rules out the possibility that a human ever assigned the mission"},{"id":"d","text":"It proves the state machine itself is broken"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-autonomy-05-o1-c1', 'mission-vec-autonomy-05-o1', 1, 'multiple_choice', 'A recovery behavior is best described as...', '{"question":"A recovery behavior is best described as...","options":[{"id":"a","text":"A permanent shutdown triggered by any error"},{"id":"b","text":"A bounded, automatic fallback action -- like clearing a costmap or backing up and retrying -- tried before the stack gives up, with a hard limit so it cannot retry a hopeless action forever"},{"id":"c","text":"A behavior that only a human can trigger manually"},{"id":"d","text":"The same thing as a state transition"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-autonomy-05-o2-c1', 'mission-vec-autonomy-05-o2', 1, 'investigation', 'Which piece of evidence proves Recon Seven never attempted a recovery behavior at all?', '{"evidence":[{"id":"e1","label":"Recovery log","detail":"Zero recovery behaviors were attempted or logged before Recon Seven entered REFUSED"},{"id":"e2","label":"Sensor log","detail":"All onboard sensors reported nominal status throughout"},{"id":"e3","label":"Power log","detail":"Battery charge remained above ninety percent the entire time"}],"question":"Which piece of evidence proves Recon Seven never attempted a recovery behavior at all?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-vec-autonomy-06-o1-c1', 'mission-vec-autonomy-06-o1', 1, 'multiple_choice', 'Goal selection is best described as...', '{"question":"Goal selection is best described as...","options":[{"id":"a","text":"Always picking whichever candidate route is shortest on paper"},{"id":"b","text":"Weighing candidate routes by cost, feasibility and priority, and choosing the one that actually clears every check -- a route that fails feasibility is not a worse candidate, it is not a valid one at all"},{"id":"c","text":"A random choice among all technically drawable paths"},{"id":"d","text":"A decision made once at the start of the mission and never revisited"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-autonomy-06-o2-c1', 'mission-vec-autonomy-06-o2', 1, 'multiple_choice', 'Recon Seven''s planner produced no feasible route into Sector Talon at all. What does that imply about goal selection here?', '{"question":"Recon Seven''s planner produced no feasible route into Sector Talon at all. What does that imply about goal selection here?","options":[{"id":"a","text":"The selector failed to run"},{"id":"b","text":"There was no valid candidate for it to choose between -- goal selection cannot select a route that the planner never validated as feasible in the first place"},{"id":"c","text":"It implies the selector chose the worst available option"},{"id":"d","text":"It implies a hardware fault in the selection logic"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-autonomy-07-o1-c1', 'mission-vec-autonomy-07-o1', 1, 'interactive_diagram', 'Order the navigation stack''s pieces from a map of the world to actual motion.', '{"diagramId":"navigation-stack-layers","hotspots":[{"id":"global_costmap","label":"Global costmap","explanation":"A map of the whole known area, updated as new information arrives."},{"id":"global_planner","label":"Global planner","explanation":"Finds a full route across the global costmap toward the goal."},{"id":"local_costmap","label":"Local costmap","explanation":"A live, close-range map built from current sensor data."},{"id":"local_controller","label":"Local controller","explanation":"Steers moment to moment along the route using the local costmap."}],"task":"Order the pieces from a map of the world to actual motion."}'::jsonb, '{"correctOrderIds":["global_costmap","global_planner","local_costmap","local_controller"]}'::jsonb),
  ('mission-vec-autonomy-07-o2-c1', 'mission-vec-autonomy-07-o2', 1, 'investigation', 'Which piece of evidence identifies what an empty region of Recon Seven''s global costmap actually means?', '{"evidence":[{"id":"e1","label":"Costmap dump","detail":"The global costmap region covering Sector Talon is empty -- no confirmed obstacle or free-space data was ever written there"},{"id":"e2","label":"Sensor log","detail":"Recon Seven''s onboard sensors reported nominal status the entire time"},{"id":"e3","label":"Facilities note","detail":"Sector Talon was scheduled for a mapping survey that was later postponed"}],"question":"Which piece of evidence identifies what an empty region of Recon Seven''s global costmap actually means?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-vec-autonomy-08-o1-c1', 'mission-vec-autonomy-08-o1', 1, 'multiple_choice', 'Docking behaviors are typically built to abort rather than push through low alignment confidence because...', '{"question":"Docking behaviors are typically built to abort rather than push through low alignment confidence because...","options":[{"id":"a","text":"Docking hardware is always more fragile than the rest of the robot"},{"id":"b","text":"Docking tolerances are measured in millimeters, so acting on an uncertain alignment risks real damage or a failed connection -- refusing the last few centimeters is safer than guessing them"},{"id":"c","text":"Docking is never actually automated"},{"id":"d","text":"Aborting is simply faster than completing the approach"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-autonomy-08-o2-c1', 'mission-vec-autonomy-08-o2', 1, 'multiple_choice', 'A docking robot''s alignment sensor confidence drops sharply during the final approach, with the port still several centimeters out of tolerance. What should it do?', '{"question":"A docking robot''s alignment sensor confidence drops sharply during the final approach, with the port still several centimeters out of tolerance. What should it do?","options":[{"id":"a","text":"Push forward at reduced speed and hope the alignment corrects itself"},{"id":"b","text":"Abort the docking attempt and report the confidence drop, rather than complete an approach it cannot verify"},{"id":"c","text":"Complete the dock exactly as planned, since it already committed to the approach"},{"id":"d","text":"Ignore the sensor and rely on the original plan only"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-autonomy-09-o1-c1', 'mission-vec-autonomy-09-o1', 1, 'multiple_choice', 'Fleet coordination is best described as...', '{"question":"Fleet coordination is best described as...","options":[{"id":"a","text":"Giving every robot in a fleet an identical, fixed route"},{"id":"b","text":"A shared map plus reservations on contested space and a clear priority rule, so two autonomous robots do not plan routes that collide"},{"id":"c","text":"A single robot''s internal planning logic, unrelated to other robots"},{"id":"d","text":"A rule that only humans can resolve conflicts between robots"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-autonomy-09-o2-c1', 'mission-vec-autonomy-09-o2', 1, 'multiple_choice', 'What principle does fleet coordination share with Recon Seven''s own refusal, even though Recon Seven was operating alone?', '{"question":"What principle does fleet coordination share with Recon Seven''s own refusal, even though Recon Seven was operating alone?","options":[{"id":"a","text":"Both are about robots moving as fast as possible"},{"id":"b","text":"Both refuse to act on a decision that cannot be verified against reality -- whether that reality is another robot''s reserved path or an unmapped stretch of ground"},{"id":"c","text":"Both rely entirely on human confirmation for every step"},{"id":"d","text":"There is no real overlap between the two"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-autonomy-10-o1-c1', 'mission-vec-autonomy-10-o1', 1, 'multiple_choice', 'A human override is best described as...', '{"question":"A human override is best described as...","options":[{"id":"a","text":"A suggestion the autonomy stack may choose to consider"},{"id":"b","text":"A command from a human operator that always takes priority over whatever the autonomy stack was about to decide on its own, the instant it arrives"},{"id":"c","text":"Something only available before a mission starts, not during"},{"id":"d","text":"A permanent setting that disables autonomy entirely"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-autonomy-10-o2-c1', 'mission-vec-autonomy-10-o2', 1, 'multiple_choice', 'What is the actual difference between an operator''s override and an autonomy stack acting on uncertain information?', '{"question":"What is the actual difference between an operator''s override and an autonomy stack acting on uncertain information?","options":[{"id":"a","text":"There is no real difference, both are just decisions"},{"id":"b","text":"The operator is a person consciously accepting a specific, known risk with context the robot lacks; the stack acting on uncertainty would be silently guessing and presenting that guess as a confident decision"},{"id":"c","text":"An override is always slower to execute"},{"id":"d","text":"The stack is always more accurate than a human operator"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-autonomy-11-o1-c1', 'mission-vec-autonomy-11-o1', 1, 'multiple_choice', 'An autonomy stack''s operational boundary is best described as...', '{"question":"An autonomy stack''s operational boundary is best described as...","options":[{"id":"a","text":"A hard physical fence around the robot''s worksite"},{"id":"b","text":"The set of conditions its decisions were actually validated under -- outside that boundary its output is not degraded judgment, it is a guess wearing the same interface as a decision"},{"id":"c","text":"A setting an operator can raise or lower at will with no consequence"},{"id":"d","text":"The maximum speed the robot is physically capable of"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-autonomy-11-o2-c1', 'mission-vec-autonomy-11-o2', 1, 'multiple_choice', 'A stack is running normally, with every sensor reporting healthy and every layer executing without error. Does that alone prove it is operating inside its validated boundary?', '{"question":"A stack is running normally, with every sensor reporting healthy and every layer executing without error. Does that alone prove it is operating inside its validated boundary?","options":[{"id":"a","text":"Yes, healthy execution is proof enough"},{"id":"b","text":"No -- a stack can run perfectly and still be asked to decide about conditions it was never actually validated for, and running smoothly says nothing about whether that specific decision is trustworthy"},{"id":"c","text":"Yes, because sensors cannot be wrong once installed"},{"id":"d","text":"No, because a healthy stack can never actually make a decision"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-autonomy-12-o1-c1', 'mission-vec-autonomy-12-o1', 1, 'investigation', 'Which combination of evidence identifies the exact node and state transition that triggered Recon Seven''s refusal?', '{"evidence":[{"id":"e1","label":"Behavior tree trace","detail":"A condition node checking localization confidence sits directly in front of the navigate action, inside a selector; the condition evaluated false and the selector fell through to REFUSED"},{"id":"e2","label":"State machine log","detail":"Recon Seven transitioned IDLE, then PLANNING, then REFUSED, never reaching EXECUTING"},{"id":"e3","label":"Power log","detail":"Battery and drivetrain power stayed nominal throughout"}],"question":"Which combination of evidence identifies the exact node and state transition that triggered Recon Seven''s refusal?"}'::jsonb, '{"requiredEvidenceIds":["e1","e2"]}'::jsonb),
  ('mission-vec-autonomy-12-o2-c1', 'mission-vec-autonomy-12-o2', 1, 'investigation', 'Which evidence proves the localization confidence guard fired on a genuine gap, not a false trigger?', '{"evidence":[{"id":"e1","label":"Costmap dump","detail":"The global costmap for that stretch of Sector Talon is empty -- no confirmed map data was ever written there"},{"id":"e2","label":"Localization log","detail":"No successful localization fix was recorded for that stretch in the entire mission history"},{"id":"e3","label":"Sensor log","detail":"All onboard sensors reported nominal health the entire time, with no fault flagged anywhere"}],"question":"Which evidence proves the localization confidence guard fired on a genuine gap, not a false trigger from a malfunctioning sensor?"}'::jsonb, '{"requiredEvidenceIds":["e1","e2"]}'::jsonb),
  ('mission-vec-autonomy-12-o3-c1', 'mission-vec-autonomy-12-o3', 1, 'multiple_choice', 'Recon Seven''s refusal is confirmed as a genuine boundary case, not a bug. What is the correct next step?', '{"question":"Recon Seven''s refusal is confirmed as a genuine boundary case, not a bug. What is the correct next step?","options":[{"id":"a","text":"Disable the localization confidence check permanently so future missions in that sector do not stall"},{"id":"b","text":"Force the autonomy stack to proceed anyway, since the mission still needs to be completed"},{"id":"c","text":"A human operator, with full awareness of the specific risk, may consciously choose to override and proceed -- but the autonomy stack itself must not act on uncertainty it cannot resolve"},{"id":"d","text":"Restart the robot repeatedly until the check happens not to trigger"}]}'::jsonb, '{"correctOptionId":"c"}'::jsonb),
  ('mission-vec-autonomy-12-o4-c1', 'mission-vec-autonomy-12-o4', 1, 'boss_encounter', 'Having traced the node, proven the boundary and confirmed the correct next step, state Recon Seven''s diagnosis.', '{"stages":[{"objectiveRef":"mission-vec-autonomy-12-o1","label":"Trace the refusal to its source node"},{"objectiveRef":"mission-vec-autonomy-12-o2","label":"Prove the boundary is genuine"},{"objectiveRef":"mission-vec-autonomy-12-o3","label":"Confirm the correct next step"}],"task":"State the diagnosis in one sentence: Recon Seven''s refusal was never a malfunction -- its behavior tree correctly gated navigation behind a localization confidence check, that check correctly found no validated confidence for that stretch of Sector Talon, and the only safe next move is a human operator consciously overriding with full awareness of the risk, not the stack guessing on its own. The safest autonomous system is not the one that always finishes the mission. It is the one that knows what it does not know."}'::jsonb, '{"requiredObjectiveIds":["mission-vec-autonomy-12-o1","mission-vec-autonomy-12-o2","mission-vec-autonomy-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-vec-autonomy-01-o1-c1', 'orientation', 'Ask whether each layer only ever executes a fixed script, or can independently decide it lacks confidence to proceed.', 10, 1),
  ('mission-vec-autonomy-01-o1-c1', 'solution', 'An autonomy stack is layered -- perception, mission planning, behavior execution, control -- and any one of those layers can refuse independently.', 20, 2),
  ('mission-vec-autonomy-01-o2-c1', 'orientation', 'A healthy status report and a correct decision are not the same claim.', 10, 1),
  ('mission-vec-autonomy-01-o2-c1', 'solution', 'Nothing can be concluded yet -- a genuine safety refusal and a bug can both look identical from the outside, and only reading the triggering layer tells them apart.', 20, 2),

  ('mission-vec-autonomy-02-o1-c1', 'orientation', 'Think about what stands between a single sentence goal and an actual sequence of waypoints.', 10, 1),
  ('mission-vec-autonomy-02-o1-c1', 'solution', 'A mission planner translates a goal into a concrete, validated sequence of reachable waypoints, checked against the map and the robot''s own capabilities.', 20, 2),
  ('mission-vec-autonomy-02-o2-c1', 'orientation', 'Ask which is more honest: a guessed plan, or no plan at all.', 10, 1),
  ('mission-vec-autonomy-02-o2-c1', 'solution', 'No usable plan is the planner being honest about failing to validate any reachable sequence -- refusing to output one beats guessing.', 20, 2),

  ('mission-vec-autonomy-03-o1-c1', 'orientation', 'Ask whether the node needs every child to succeed, only one child to succeed, checks a fact, or does something physical.', 10, 1),
  ('mission-vec-autonomy-03-o1-c1', 'solution', 'Sequence needs every child to succeed in order. Selector tries children until one succeeds. Condition checks true or false. Action actually performs a step.', 20, 2),
  ('mission-vec-autonomy-03-o2-c1', 'orientation', 'Look for the piece of evidence that names the exact node, not the ones about build health or chassis maintenance.', 10, 1),
  ('mission-vec-autonomy-03-o2-c1', 'solution', 'e1: a condition node sits directly in front of the navigate action, gating whether it is ever reached.', 20, 2),

  ('mission-vec-autonomy-04-o1-c1', 'orientation', 'A state machine cares about mode and guarded transitions, not moment-to-moment decisions.', 10, 1),
  ('mission-vec-autonomy-04-o1-c1', 'solution', 'It enforces a fixed set of named modes and the specific guarded rules for which transitions between them are allowed.', 20, 2),
  ('mission-vec-autonomy-04-o2-c1', 'orientation', 'Notice which state never appears in the log at all.', 10, 1),
  ('mission-vec-autonomy-04-o2-c1', 'solution', 'Since EXECUTING never appears, any failure during actual execution is ruled out -- the stop happened during planning, before any guard let it proceed.', 20, 2),

  ('mission-vec-autonomy-05-o1-c1', 'orientation', 'Think about why an automatic retry needs a hard stop, not just a retry.', 10, 1),
  ('mission-vec-autonomy-05-o1-c1', 'solution', 'A recovery behavior is a bounded automatic fallback -- clear a costmap, back up, retry -- with a hard limit so it cannot retry a hopeless action forever.', 20, 2),
  ('mission-vec-autonomy-05-o2-c1', 'orientation', 'Look for the log that directly counts recovery attempts, not sensor or power status.', 10, 1),
  ('mission-vec-autonomy-05-o2-c1', 'solution', 'e1: zero recovery behaviors were attempted or logged before Recon Seven entered REFUSED.', 20, 2),

  ('mission-vec-autonomy-06-o1-c1', 'orientation', 'A cheap candidate that fails feasibility is not merely a worse choice.', 10, 1),
  ('mission-vec-autonomy-06-o1-c1', 'solution', 'Goal selection weighs feasible candidates by cost, feasibility and priority -- a candidate that fails feasibility was never a valid option at all.', 20, 2),
  ('mission-vec-autonomy-06-o2-c1', 'orientation', 'A selector can only choose among candidates that actually exist.', 10, 1),
  ('mission-vec-autonomy-06-o2-c1', 'solution', 'No feasible route existed for the selector to choose between in the first place -- the absence is evidence about the candidates, not a selection failure.', 20, 2),

  ('mission-vec-autonomy-07-o1-c1', 'orientation', 'A route has to be found across the whole known map before a robot can steer along it moment to moment.', 10, 1),
  ('mission-vec-autonomy-07-o1-c1', 'solution', 'Global costmap, then global planner, then local costmap, then local controller -- world-scale route first, close-range steering last.', 20, 2),
  ('mission-vec-autonomy-07-o2-c1', 'orientation', 'The costmap dump is the only evidence that directly describes what is missing from the map itself.', 10, 1),
  ('mission-vec-autonomy-07-o2-c1', 'solution', 'e1: the global costmap region over Sector Talon is empty, meaning no confirmed data was ever written there at all.', 20, 2),

  ('mission-vec-autonomy-08-o1-c1', 'orientation', 'Think about the scale of the tolerance docking actually requires, compared to a normal corridor.', 10, 1),
  ('mission-vec-autonomy-08-o1-c1', 'solution', 'Docking tolerances are measured in millimeters, so an uncertain alignment risks real damage -- refusing the last centimeters beats guessing them.', 20, 2),
  ('mission-vec-autonomy-08-o2-c1', 'orientation', 'A dropping confidence signal during the most sensitive part of the approach is not something to push through.', 10, 1),
  ('mission-vec-autonomy-08-o2-c1', 'solution', 'It should abort and report the confidence drop rather than complete an approach it can no longer verify.', 20, 2),

  ('mission-vec-autonomy-09-o1-c1', 'orientation', 'Think about what has to be shared between robots so their plans do not overlap.', 10, 1),
  ('mission-vec-autonomy-09-o1-c1', 'solution', 'Fleet coordination is a shared map plus reservations on contested space and a clear priority rule for who yields.', 20, 2),
  ('mission-vec-autonomy-09-o2-c1', 'orientation', 'Both concepts refuse to act on something the stack cannot actually verify.', 10, 1),
  ('mission-vec-autonomy-09-o2-c1', 'solution', 'Both refuse to act on a decision that cannot be verified against reality, whether that reality is another robot''s reserved path or unmapped ground.', 20, 2),

  ('mission-vec-autonomy-10-o1-c1', 'orientation', 'An override is not optional input for the stack to weigh -- it wins immediately.', 10, 1),
  ('mission-vec-autonomy-10-o1-c1', 'solution', 'A human override is a command that always takes priority over whatever the autonomy stack was about to decide, the instant it arrives.', 20, 2),
  ('mission-vec-autonomy-10-o2-c1', 'orientation', 'Ask who is actually aware of the risk being taken in each case.', 10, 1),
  ('mission-vec-autonomy-10-o2-c1', 'solution', 'The operator consciously accepts a known risk with context the robot lacks; the stack acting on uncertainty would be silently guessing while looking confident.', 20, 2),

  ('mission-vec-autonomy-11-o1-c1', 'orientation', 'The boundary is about what was actually validated, not about a physical limit.', 10, 1),
  ('mission-vec-autonomy-11-o1-c1', 'solution', 'It is the set of conditions the stack''s decisions were actually validated under -- outside it, output is a guess wearing a decision''s interface.', 20, 2),
  ('mission-vec-autonomy-11-o2-c1', 'orientation', 'Running without error only tells you the code executed, not that the specific decision was trustworthy.', 10, 1),
  ('mission-vec-autonomy-11-o2-c1', 'solution', 'No -- a stack can run perfectly while being asked to decide about conditions it was never validated for.', 20, 2),

  ('mission-vec-autonomy-12-o1-c1', 'orientation', 'You need both the exact node from the tree and the exact transition from the state log to trace it fully.', 10, 1),
  ('mission-vec-autonomy-12-o1-c1', 'solution', 'e1 and e2 together: the localization confidence condition inside the selector evaluated false, matching the state log''s stop in PLANNING before EXECUTING.', 20, 2),
  ('mission-vec-autonomy-12-o2-c1', 'orientation', 'Genuine proof needs both an empty costmap and a matching localization log, not just one.', 10, 1),
  ('mission-vec-autonomy-12-o2-c1', 'solution', 'e1 and e2 together: an empty costmap region and zero successful localization fixes for that stretch confirm the gap is real, not a sensor glitch.', 20, 2),
  ('mission-vec-autonomy-12-o3-c1', 'orientation', 'Think back to the human override mission -- who is allowed to consciously accept this exact kind of risk.', 10, 1),
  ('mission-vec-autonomy-12-o3-c1', 'solution', 'A human operator may consciously override with full awareness of the risk; the autonomy stack itself must never guess on its own.', 20, 2),
  ('mission-vec-autonomy-12-o4-c1', 'orientation', 'Combine the exact node, the proof the gap is real, and who is allowed to act on it into one diagnosis.', 15, 1),
  ('mission-vec-autonomy-12-o4-c1', 'concept', 'The refusal was not a bug -- it was a localization confidence guard correctly firing over genuinely unvalidated ground, deferring the decision to a human who can knowingly accept the risk.', 25, 2),
  ('mission-vec-autonomy-12-o4-c1', 'solution', 'Recon Seven''s refusal traces to a real localization confidence gate over a genuinely unvalidated stretch of Sector Talon; the correct next move belongs to a human operator consciously overriding, never the stack guessing on its own -- the safest autonomous system is the one that knows what it does not know.', 30, 3);
